1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { createPortal } from "react-dom";
5	import type { Terminal as XTerm } from "@xterm/xterm";
6	import type { FitAddon as XFitAddon } from "@xterm/addon-fit";
7	import "@xterm/xterm/css/xterm.css";
8	
9	/**
10	 * In-portal web terminal — a slide-in panel with an xterm.js terminal wired to
11	 * a real root shell on one of the customer's running servers.
12	 *
13	 * Security: the websocket is authorized by a short-lived token minted by
14	 * POST /api/terminal/token (which checks the session + ownership). This
15	 * component never sees any server credential — only the opaque token.
16	 *
17	 * Wire protocol (matches terminal-server/index.ts):
18	 *   client → server : JSON  {type:"data",data} | {type:"resize",cols,rows}
19	 *   server → client : raw shell output (text or binary) → written to xterm
20	 */
21	
22	export type TerminalServer = { id: string; hostname: string };
23	
24	type Status = "idle" | "connecting" | "connected" | "closed" | "error";
25	
26	export function WebTerminal({
27	  servers,
28	  onClose,
29	  embedded = false,
30	  hint,
31	}: {
32	  servers: TerminalServer[];
33	  /** Overlay mode only. Optional in embedded mode (no chrome to close). */
34	  onClose?: () => void;
35	  /**
36	   * When true, render inline (fills its parent) instead of as a full-screen
37	   * slide-in portal. Used to give each Matrix console its own terminal.
38	   */
39	  embedded?: boolean;
40	  /** Optional one-line idle hint shown before the first connect. */
41	  hint?: string;
42	}) {
43	  const [mounted, setMounted] = useState(false);
44	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
45	  const [status, setStatus] = useState<Status>("idle");
46	  const [error, setError] = useState<string | null>(null);
47	
48	  const hostRef = useRef<HTMLDivElement | null>(null);
49	  const termRef = useRef<XTerm | null>(null);
50	  const fitRef = useRef<XFitAddon | null>(null);
51	  const wsRef = useRef<WebSocket | null>(null);
52	  const roRef = useRef<ResizeObserver | null>(null);
53	  const disposedRef = useRef(false);
54	
55	  useEffect(() => {
56	    setMounted(true);
57	    return () => {
58	      disposedRef.current = true;
59	    };
60	  }, []);
61	
62	  const selected = useMemo(
63	    () => servers.find((s) => s.id === serverId) ?? null,
64	    [servers, serverId]
65	  );
66	
67	  /** Tear down the live websocket + terminal (idempotent). */
68	  function teardown() {
69	    try {
70	      roRef.current?.disconnect();
71	    } catch {
72	      /* ignore */
73	    }
74	    roRef.current = null;
75	    try {
76	      wsRef.current?.close();
77	    } catch {
78	      /* ignore */
79	    }
80	    wsRef.current = null;
81	    try {
82	      termRef.current?.dispose();
83	    } catch {
84	      /* ignore */
85	    }
86	    termRef.current = null;
87	    fitRef.current = null;
88	  }
89	
90	  useEffect(() => {
91	    // Clean up whenever the panel unmounts.
92	    return () => teardown();
93	    // eslint-disable-next-line react-hooks/exhaustive-deps
94	  }, []);
95	
96	  function sendResize() {
97	    const term = termRef.current;
98	    const fit = fitRef.current;
99	    const ws = wsRef.current;
100	    if (!term || !fit) return;
101	    try {
102	      fit.fit();
103	    } catch {
104	      /* ignore */
105	    }
106	    if (ws && ws.readyState === WebSocket.OPEN) {
107	      ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
108	    }
109	  }
110	
111	  async function connect() {
112	    if (!serverId) return;
113	    setError(null);
114	    setStatus("connecting");
115	    teardown();
116	
117	    // 1. Mint a short-lived token (session + ownership checked server-side).
118	    let token: string;
119	    try {
120	      const res = await fetch("/api/terminal/token", {
121	        method: "POST",
122	        headers: { "Content-Type": "application/json" },
123	        body: JSON.stringify({ serverId }),
124	      });
125	      const body = await res.json().catch(() => ({}));
126	      if (!res.ok) throw new Error(body?.error || "Could not authorize the terminal.");
127	      token = body.token;
128	      if (!token) throw new Error("No terminal token was issued.");
129	    } catch (e) {
130	      setStatus("error");
131	      setError(e instanceof Error ? e.message : "Could not authorize the terminal.");
132	      return;
133	    }
134	    if (disposedRef.current) return;
135	
136	    // 2. Build the terminal.
137	    const [{ Terminal }, { FitAddon }] = await Promise.all([
138	      import("@xterm/xterm"),
139	      import("@xterm/addon-fit"),
140	    ]);
141	    if (disposedRef.current || !hostRef.current) return;
142	
143	    const term = new Terminal({
144	      cursorBlink: true,
145	      fontFamily:
146	        'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
147	      fontSize: 13,
148	      theme: { background: "#0a0e1a", foreground: "#e2e8f0", cursor: "#e2e8f0" },
149	    });
150	    const fit = new FitAddon();
151	    term.loadAddon(fit);
152	    term.open(hostRef.current);
153	    try {
154	      fit.fit();
155	    } catch {
156	      /* ignore */
157	    }
158	    termRef.current = term;
159	    fitRef.current = fit;
160	
161	    // 3. Open the websocket to the PTY backend (nginx proxies /terminal-ws).
162	    const scheme = location.protocol === "https:" ? "wss" : "ws";
163	    const ws = new WebSocket(
164	      `${scheme}://${location.host}/terminal-ws?token=${encodeURIComponent(token)}`
165	    );
166	    ws.binaryType = "arraybuffer";
167	    wsRef.current = ws;
168	
169	    ws.onopen = () => {
170	      setStatus("connected");
171	      term.focus();
172	      sendResize();
173	    };
174	    ws.onmessage = (ev) => {
175	      if (typeof ev.data === "string") {
176	        term.write(ev.data);
177	      } else if (ev.data instanceof ArrayBuffer) {
178	        term.write(new Uint8Array(ev.data));
179	      }
180	    };
181	    ws.onerror = () => {
182	      setError("Connection error.");
183	    };
184	    ws.onclose = (ev) => {
185	      setStatus((s) => (s === "error" ? s : "closed"));
186	      if (ev.reason && termRef.current) {
187	        term.write(`\r\n\x1b[90m[${ev.reason}]\x1b[0m\r\n`);
188	      }
189	    };
190	
191	    // 4. Keystrokes → server.
192	    term.onData((data) => {
193	      if (ws.readyState === WebSocket.OPEN) {
194	        ws.send(JSON.stringify({ type: "data", data }));
195	      }
196	    });
197	
198	    // 5. Keep the PTY window sized to the panel.
199	    const ro = new ResizeObserver(() => sendResize());
200	    if (hostRef.current) ro.observe(hostRef.current);
201	    roRef.current = ro;
202	  }
203	
204	  function disconnect() {
205	    teardown();
206	    setStatus("closed");
207	  }
208	
209	  const statusLabel: Record<Status, string> = {
210	    idle: "Not connected",
211	    connecting: "Connecting…",
212	    connected: "Connected",
213	    closed: "Disconnected",
214	    error: "Error",
215	  };
216	  const statusColor: Record<Status, string> = {
217	    idle: "bg-slate-500",
218	    connecting: "bg-amber-400 animate-pulse",
219	    connected: "bg-emerald-400",
220	    closed: "bg-slate-500",
221	    error: "bg-red-500",
222	  };
223	  const live = status === "connected" || status === "connecting";
224	
225	  if (!mounted) return null;
226	
227	  const body = (
228	    <>
229	        {/* Header */}
230	        <div className="flex flex-none items-center gap-3 border-b border-white/[0.06] px-4 py-3">
231	          <div className="flex items-center gap-2">
232	            <span className={`h-2.5 w-2.5 rounded-full ${statusColor[status]}`} />
233	            <span className="text-sm font-semibold text-white">Terminal</span>
234	            <span className="text-xs text-slate-400">{statusLabel[status]}</span>
235	          </div>
236	
237	          <div className="ml-auto flex items-center gap-2">
238	            <select
239	              value={serverId}
240	              onChange={(e) => setServerId(e.target.value)}
241	              disabled={live}
242	              className="max-w-[10rem] rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-xs text-white outline-none focus:border-brand-400/60 disabled:opacity-50"
243	            >
244	              {servers.length === 0 && <option value="">No running servers</option>}
245	              {servers.map((s) => (
246	                <option key={s.id} value={s.id} className="bg-navy-900">
247	                  {s.hostname}
248	                </option>
249	              ))}
250	            </select>
251	
252	            {live ? (
253	              <button
254	                onClick={disconnect}
255	                className="rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-xs font-semibold text-slate-200 hover:bg-white/10"
256	              >
257	                Disconnect
258	              </button>
259	            ) : (
260	              <button
261	                onClick={connect}
262	                disabled={!serverId}
263	                className="rounded-lg bg-brand-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-400 disabled:opacity-50"
264	              >
265	                Connect
266	              </button>
267	            )}
268	
269	            {onClose && (
270	              <button
271	                onClick={onClose}
272	                className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white"
273	                aria-label="Close terminal"
274	              >
275	                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
276	                  <path d="M18 6 6 18M6 6l12 12" />
277	                </svg>
278	              </button>
279	            )}
280	          </div>
281	        </div>
282	
283	        {/* Error banner */}
284	        {error && (
285	          <div className="flex-none border-b border-red-500/20 bg-red-500/10 px-4 py-2 text-xs text-red-200">
286	            {error}
287	          </div>
288	        )}
289	
290	        {/* Hint before first connect */}
291	        {status === "idle" && (
292	          <div className="flex-none border-b border-white/[0.06] bg-white/[0.02] px-4 py-2 text-xs text-slate-400">
293	            {hint
294	              ? hint
295	              : selected
296	                ? <>Opens a root shell on <span className="font-semibold text-slate-200">{selected.hostname}</span>. Run <code className="rounded bg-white/10 px-1 text-slate-200">claude</code> to start building.</>
297	                : "Pick a running server, then press Connect."}
298	          </div>
299	        )}
300	
301	        {/* Terminal surface */}
302	        <div className="min-h-0 flex-1 bg-[#0a0e1a] p-2">
303	          <div ref={hostRef} className="h-full w-full" />
304	        </div>
305	    </>
306	  );
307	
308	  // Embedded: render inline, filling the console pane. No portal, no backdrop.
309	  if (embedded) {
310	    return (
311	      <div className="flex h-full min-h-0 flex-col overflow-hidden rounded-2xl border border-white/[0.08] bg-navy-900/70">
312	        {body}
313	      </div>
314	    );
315	  }
316	
317	  // Overlay: full-screen slide-in panel.
318	  return createPortal(
319	    <div className="fixed inset-0 z-[70] flex justify-end" role="dialog" aria-modal="true">
320	      {/* Backdrop */}
321	      <div
322	        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
323	        onClick={onClose}
324	        aria-hidden
325	      />
326	
327	      {/* Slide-in panel */}
328	      <div className="relative flex h-full w-full max-w-3xl flex-col border-l border-white/10 bg-navy-900 shadow-2xl md:w-1/2">
329	        {body}
330	      </div>
331	    </div>,
332	    document.body
333	  );
334	}
