1	"use server";
2	
3	/**
4	 * Owned-server-scoped server actions for the in-portal file manager.
5	 *
6	 * Every action:
7	 *   - authenticates the caller and verifies they OWN the target server
8	 *     (admins may act on any server), mirroring the `ownedServer` pattern in
9	 *     lib/actions-server-lifecycle.ts;
10	 *   - normalizes + validates the path (rejects `..` traversal, requires an
11	 *     absolute path, clamps length) via lib/sftp helpers;
12	 *   - enforces size limits on text edits;
13	 *   - rate-limits per user;
14	 *   - returns a typed { ok, error?, ... } result — never throws raw internals
15	 *     at the client, and never exposes another user's server.
16	 *
17	 * The heavy lifting (real SFTP vs. sandbox simulation) lives in lib/sftp.ts.
18	 */
19	import { db } from "./db";
20	import { requireUser } from "./auth";
21	import { checkRateLimit } from "./rate-limit";
22	import type { FileEntry } from "./files-types";
23	import {
24	  listDir,
25	  statPath,
26	  readFileText,
27	  writeFileText,
28	  mkdirPath,
29	  renamePath,
30	  removePath,
31	  chmodPath,
32	  normalizePath,
33	  validateName,
34	  joinPath,
35	  type SftpEntry,
36	} from "./sftp";
37	
38	/** Max size (bytes) for a text file opened/saved in the inline editor. */
39	const MAX_EDIT_BYTES = 1024 * 1024; // ~1 MB
40	
41	type ListResult = { ok: true; path: string; entries: FileEntry[] } | { ok: false; error: string };
42	type ReadResult =
43	  | { ok: true; path: string; content: string; truncated: false }
44	  | { ok: false; error: string };
45	type MutResult = { ok: true } | { ok: false; error: string };
46	
47	/**
48	 * Load the server if (and only if) the caller owns it (or is an admin). Returns
49	 * the exact fields lib/sftp needs to open a connection. Throws generic errors
50	 * that the wrappers translate to typed results.
51	 */
52	async function ownedServer(serverId: string) {
53	  const user = await requireUser();
54	  const server = await db.server.findUnique({
55	    where: { id: serverId },
56	    select: {
57	      id: true,
58	      userId: true,
59	      status: true,
60	      rootPassword: true,
61	      rootPasswordEnc: true,
62	      sshPort: true,
63	      dedicatedIp: { select: { address: true } },
64	    },
65	  });
66	  if (!server) throw new Error("Not found");
67	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
68	  return { user, server };
69	}
70	
71	/** Per-user throttle. Returns an error string when the caller should back off. */
72	function throttle(userId: string, op: string, max: number): string | null {
73	  const rl = checkRateLimit(`files:${op}:${userId}`, { max, windowMs: 60_000 });
74	  if (!rl.ok) return `Too many requests — slow down and retry in ${rl.retryAfterSec}s.`;
75	  return null;
76	}
77	
78	function toMode(mode: number | null): string | null {
79	  return mode == null ? null : (mode & 0o777).toString(8).padStart(3, "0");
80	}
81	
82	function entryOut(e: SftpEntry): FileEntry {
83	  return {
84	    name: e.name,
85	    isDirectory: e.isDirectory,
86	    size: e.size,
87	    modifiedMs: e.modifiedMs,
88	    mode: toMode(e.mode),
89	  };
90	}
91	
92	/** Map an internal error to a safe, user-facing message. */
93	function safeError(err: unknown): string {
94	  const msg = err instanceof Error ? err.message : String(err);
95	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
96	  // Path/traversal/size messages from lib/sftp are already user-safe.
97	  if (
98	    /traversal|absolute|too long|too large|Invalid|No such|Not a (file|directory)|already exists|reachable|root password|is a directory/i.test(
99	      msg
100	    )
101	  ) {
102	    return msg;
103	  }
104	  // Anything else (connection/protocol errors) — keep it generic.
105	  return "Could not reach the server's filesystem. Please try again shortly.";
106	}
107	
108	// ---------------------------------------------------------------------------
109	
110	export async function listFiles(serverId: string, path: string): Promise<ListResult> {
111	  try {
112	    const { user, server } = await ownedServer(serverId);
113	    const limited = throttle(user.id, "list", 120);
114	    if (limited) return { ok: false, error: limited };
115	    const clean = normalizePath(path || "/");
116	    const entries = await listDir(server, clean);
117	    return { ok: true, path: clean, entries: entries.map(entryOut) };
118	  } catch (err) {
119	    return { ok: false, error: safeError(err) };
120	  }
121	}
122	
123	export async function readFile(serverId: string, path: string): Promise<ReadResult> {
124	  try {
125	    const { user, server } = await ownedServer(serverId);
126	    const limited = throttle(user.id, "read", 120);
127	    if (limited) return { ok: false, error: limited };
128	    const clean = normalizePath(path);
129	    const content = await readFileText(server, clean, MAX_EDIT_BYTES);
130	    return { ok: true, path: clean, content, truncated: false };
131	  } catch (err) {
132	    return { ok: false, error: safeError(err) };
133	  }
134	}
135	
136	export async function saveFile(
137	  serverId: string,
138	  path: string,
139	  content: string
140	): Promise<MutResult> {
141	  try {
142	    const { user, server } = await ownedServer(serverId);
143	    const limited = throttle(user.id, "save", 60);
144	    if (limited) return { ok: false, error: limited };
145	    if (typeof content !== "string") return { ok: false, error: "Invalid content." };
146	    if (Buffer.byteLength(content, "utf8") > MAX_EDIT_BYTES) {
147	      return { ok: false, error: "File exceeds the 1 MB in-browser edit limit." };
148	    }
149	    const clean = normalizePath(path);
150	    await writeFileText(server, clean, content);
151	    return { ok: true };
152	  } catch (err) {
153	    return { ok: false, error: safeError(err) };
154	  }
155	}
156	
157	export async function createFolder(
158	  serverId: string,
159	  path: string,
160	  name: string
161	): Promise<MutResult> {
162	  try {
163	    const { user, server } = await ownedServer(serverId);
164	    const limited = throttle(user.id, "mkdir", 60);
165	    if (limited) return { ok: false, error: limited };
166	    const dir = normalizePath(path);
167	    const clean = validateName(name.trim());
168	    await mkdirPath(server, joinPath(dir, clean));
169	    return { ok: true };
170	  } catch (err) {
171	    return { ok: false, error: safeError(err) };
172	  }
173	}
174	
175	export async function renameEntry(
176	  serverId: string,
177	  path: string,
178	  newName: string
179	): Promise<MutResult> {
180	  try {
181	    const { user, server } = await ownedServer(serverId);
182	    const limited = throttle(user.id, "rename", 60);
183	    if (limited) return { ok: false, error: limited };
184	    const from = normalizePath(path);
185	    if (from === "/") return { ok: false, error: "The root directory cannot be renamed." };
186	    const clean = validateName(newName.trim());
187	    const parent = from.slice(0, from.lastIndexOf("/")) || "/";
188	    await renamePath(server, from, joinPath(parent, clean));
189	    return { ok: true };
190	  } catch (err) {
191	    return { ok: false, error: safeError(err) };
192	  }
193	}
194	
195	export async function deleteEntry(serverId: string, path: string): Promise<MutResult> {
196	  try {
197	    const { user, server } = await ownedServer(serverId);
198	    const limited = throttle(user.id, "delete", 60);
199	    if (limited) return { ok: false, error: limited };
200	    const clean = normalizePath(path);
201	    if (clean === "/") return { ok: false, error: "The root directory cannot be deleted." };
202	    await removePath(server, clean);
203	    return { ok: true };
204	  } catch (err) {
205	    return { ok: false, error: safeError(err) };
206	  }
207	}
208	
209	export async function chmodEntry(
210	  serverId: string,
211	  path: string,
212	  mode: string
213	): Promise<MutResult> {
214	  try {
215	    const { user, server } = await ownedServer(serverId);
216	    const limited = throttle(user.id, "chmod", 60);
217	    if (limited) return { ok: false, error: limited };
218	    const clean = normalizePath(path);
219	    if (!/^[0-7]{3,4}$/.test(mode)) {
220	      return { ok: false, error: "Mode must be an octal value like 644 or 755." };
221	    }
222	    await chmodPath(server, clean, parseInt(mode, 8));
223	    return { ok: true };
224	  } catch (err) {
225	    return { ok: false, error: safeError(err) };
226	  }
227	}
228	
229	/** Lightweight stat used to disambiguate file vs. dir before an action. */
230	export async function statEntry(
231	  serverId: string,
232	  path: string
233	): Promise<{ ok: true; isDirectory: boolean; size: number } | { ok: false; error: string }> {
234	  try {
235	    const { user, server } = await ownedServer(serverId);
236	    const limited = throttle(user.id, "stat", 120);
237	    if (limited) return { ok: false, error: limited };
238	    const clean = normalizePath(path);
239	    const s = await statPath(server, clean);
240	    return { ok: true, isDirectory: s.isDirectory, size: s.size };
241	  } catch (err) {
242	    return { ok: false, error: safeError(err) };
243	  }
244	}
245

1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { planConsoleBuild } from "@/lib/actions-claude-console";
6	import { approveBuild, rejectBuild } from "@/lib/actions-claude";
7	import { consolePhase, isBuildActive, type ConsolePhase } from "@/lib/claude-console-core";
8	import { WebTerminal } from "@/components/customer/WebTerminal";
9	
10	/** The two ways a console can build. */
11	export type BuildMode = "key" | "server";
12	
13	/* -------------------------------------------------------------------------- */
14	/* Types                                                                       */
15	/* -------------------------------------------------------------------------- */
16	
17	export type ServerOption = { id: string; hostname: string };
18	
19	type PlanStep = { cmd: string; intent?: string };
20	
21	type Turn = {
22	  key: string;
23	  prompt: string;
24	  images: string[]; // data URLs
25	  buildId: string | null;
26	  status: string | null; // ClaudeBuild.status
27	  steps: number;
28	  log: string;
29	  plan: string | null; // JSON string of proposed commands
30	  error: string | null;
31	};
32	
33	export type BuildConsoleProps = {
34	  consoleId: string;
35	  index: number;
36	  servers: ServerOption[];
37	  initialServerId: string;
38	  /** Mirror mode: a shared prompt auto-sent when the console mounts. */
39	  autoPrompt?: string;
40	  mirrorLabel?: string | null;
41	  /** Mirror mode: DB grouping id + variation title, tagged onto this console's builds. */
42	  mirrorGroupId?: string | null;
43	  buildTitle?: string | null;
44	  onRemove?: () => void;
45	  canRemove: boolean;
46	  /** Whether to render compactly (many consoles in a grid). */
47	  dense?: boolean;
48	  /** Whether an Anthropic key (BYOK or platform fallback) is available. */
49	  keyConnected: boolean;
50	  /** Which build mode this console opens in. */
51	  initialMode: BuildMode;
52	};
53	
54	/* -------------------------------------------------------------------------- */
55	/* Web Speech API (voice-to-text) — typed minimally, degrades gracefully.      */
56	/* -------------------------------------------------------------------------- */
57	
58	type SpeechRecognitionLike = {
59	  lang: string;
60	  continuous: boolean;
61	  interimResults: boolean;
62	  start: () => void;
63	  stop: () => void;
64	  onresult: ((e: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null;
65	  onerror: (() => void) | null;
66	  onend: (() => void) | null;
67	};
68	
69	function getSpeechRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
70	  if (typeof window === "undefined") return null;
71	  const w = window as unknown as {
72	    SpeechRecognition?: new () => SpeechRecognitionLike;
73	    webkitSpeechRecognition?: new () => SpeechRecognitionLike;
74	  };
75	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
76	}
77	
78	/* -------------------------------------------------------------------------- */
79	/* Helpers                                                                     */
80	/* -------------------------------------------------------------------------- */
81	
82	function parsePlan(raw: string | null): PlanStep[] {
83	  if (!raw) return [];
84	  try {
85	    const p = JSON.parse(raw);
86	    if (Array.isArray(p)) {
87	      return p
88	        .map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent }))
89	        .filter((s) => s.cmd);
90	    }
91	  } catch {
92	    /* ignore */
93	  }
94	  return [];
95	}
96	
97	const PHASE_TONE: Record<ConsolePhase, string> = {
98	  idle: "border-white/10 bg-white/5 text-slate-400",
99	  planning: "border-amber-500/40 bg-amber-500/10 text-amber-300",
100	  awaiting: "border-sky-500/40 bg-sky-500/10 text-sky-300",
101	  running: "border-brand-500/40 bg-brand-500/10 text-brand-200",
102	  done: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
103	  failed: "border-red-500/40 bg-red-500/10 text-red-300",
104	};
105	
106	const PHASE_LABEL: Record<ConsolePhase, string> = {
107	  idle: "idle",
108	  planning: "planning",
109	  awaiting: "awaiting approval",
110	  running: "running",
111	  done: "done",
112	  failed: "failed",
113	};
114	
115	let seq = 0;
116	const nextKey = () => `t${Date.now()}_${seq++}`;
117	
118	/* -------------------------------------------------------------------------- */
119	/* Component                                                                   */
120	/* -------------------------------------------------------------------------- */
121	
122	export function BuildConsole({
123	  consoleId,
124	  index,
125	  servers,
126	  initialServerId,
127	  autoPrompt,
128	  mirrorLabel,
129	  mirrorGroupId = null,
130	  buildTitle = null,
131	  onRemove,
132	  canRemove,
133	  dense = false,
134	  keyConnected,
135	  initialMode,
136	}: BuildConsoleProps) {
137	  const [mode, setMode] = useState<BuildMode>(initialMode);
138	  const [serverId, setServerId] = useState(initialServerId || servers[0]?.id || "");
139	  const [input, setInput] = useState("");
140	  const [images, setImages] = useState<string[]>([]);
141	  const [turns, setTurns] = useState<Turn[]>([]);
142	  const [pending, setPending] = useState(false);
143	  const [listening, setListening] = useState(false);
144	
145	  const scrollRef = useRef<HTMLDivElement>(null);
146	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
147	  const fileInputRef = useRef<HTMLInputElement>(null);
148	  const speechSupported = useRef<boolean>(false);
149	  const autoStarted = useRef(false);
150	
151	  useEffect(() => {
152	    speechSupported.current = getSpeechRecognitionCtor() !== null;
153	  }, []);
154	
155	  // Auto-scroll the transcript as it grows.
156	  useEffect(() => {
157	    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
158	  }, [turns]);
159	
160	  /* ------------------------------ send a plan ----------------------------- */
161	
162	  const send = useCallback(
163	    async (promptText: string, imgs: string[]) => {
164	      const clean = promptText.trim();
165	      if (clean.length < 8 || !serverId || pending) return;
166	      setPending(true);
167	      const key = nextKey();
168	      setTurns((prev) => [
169	        ...prev,
170	        { key, prompt: clean, images: imgs, buildId: null, status: "PLANNING", steps: 0, log: "", plan: null, error: null },
171	      ]);
172	      setInput("");
173	      setImages([]);
174	
175	      const res = await planConsoleBuild(serverId, clean, imgs, mirrorGroupId, buildTitle).catch((e) => ({
176	        error: e instanceof Error ? e.message : "Planning failed.",
177	      }));
178	      setTurns((prev) =>
179	        prev.map((t) =>
180	          t.key === key
181	            ? "error" in res && res.error
182	              ? { ...t, status: "FAILED", error: res.error }
183	              : { ...t, buildId: (res as { buildId?: string }).buildId ?? null, status: "AWAITING_APPROVAL" }
184	            : t
185	        )
186	      );
187	      setPending(false);
188	    },
189	    [serverId, pending, mirrorGroupId, buildTitle]
190	  );
191	
192	  // Mirror mode: fire the shared prompt once, automatically.
193	  useEffect(() => {
194	    if (autoStarted.current) return;
195	    if (autoPrompt && autoPrompt.trim().length >= 8 && serverId) {
