201	  /* ------------------------------- polling -------------------------------- */
202	
203	  // Poll the most recent turn that has a build id and is still in flight.
204	  useEffect(() => {
205	    const active = [...turns].reverse().find((t) => t.buildId && isBuildActive(t.status));
206	    if (!active?.buildId) return;
207	    let alive = true;
208	    let timer: ReturnType<typeof setTimeout>;
209	    const tick = async () => {
210	      try {
211	        const r = await fetch(`/api/claude/${active.buildId}`, { cache: "no-store" });
212	        if (r.ok) {
213	          const data = (await r.json()) as { status?: string; steps?: number; log?: string; plan?: string | null };
214	          if (alive) {
215	            setTurns((prev) =>
216	              prev.map((t) =>
217	                t.buildId === active.buildId
218	                  ? { ...t, status: data.status ?? t.status, steps: data.steps ?? t.steps, log: data.log ?? t.log, plan: data.plan ?? t.plan }
219	                  : t
220	              )
221	            );
222	          }
223	          if (data.status && ["DONE", "FAILED"].includes(data.status)) return;
224	        }
225	      } catch {
226	        /* transient */
227	      }
228	      if (alive) timer = setTimeout(tick, 2000);
229	    };
230	    void tick();
231	    return () => {
232	      alive = false;
233	      clearTimeout(timer);
234	    };
235	  }, [turns]);
