1	/**
2	 * Server-side SFTP proxy for the in-portal file manager.
3	 *
4	 * This is a plain (non-"use server") module so it can be imported by both the
5	 * server actions (lib/actions-files.ts) and the upload/download route handler.
6	 * It never runs in the browser — the customer's root credentials stay on the
7	 * server; the browser only ever talks to our own actions/route.
8	 *
9	 * Connection target is derived EXACTLY like the server detail page:
10	 *   - dedicated-IP servers connect to their own IP on port 22
11	 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
12	 * Username is always "root"; password is `server.rootPassword`.
13	 *
14	 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
15	 * every op is backed by a small in-memory simulated filesystem so the whole
16	 * file-manager UX works end to end without a live VM.
17	 */
18	import SftpClient from "ssh2-sftp-client";
19	import { SANDBOX } from "./sandbox";
20	import { decryptSecret } from "./crypto-box";
21	
22	/**
23	 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
24	 * value and falling back to the legacy plaintext column for rows that predate
25	 * encryption. Every READ of a root password must go through this helper so both
26	 * shapes keep working transparently.
27	 */
28	export function serverRootPassword(
29	  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
30	): string | null {
31	  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
32	}
33	
34	/** The minimal shape of a Server we need to open a connection. */
35	export type SftpServer = {
36	  id: string;
37	  rootPassword: string | null;
38	  rootPasswordEnc?: string | null;
39	  sshPort: number | null;
40	  dedicatedIp?: { address: string } | null;
41	};
42	
43	export type SftpEntry = {
44	  name: string;
45	  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
46	  type: string;
47	  isDirectory: boolean;
48	  size: number;
49	  /** Unix mtime in ms. */
50	  modifiedMs: number;
51	  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
52	  mode: number | null;
53	};
54	
55	export type SftpStat = {
56	  isDirectory: boolean;
57	  size: number;
58	  modifiedMs: number;
59	  mode: number | null;
60	};
61	
62	const CONNECT_TIMEOUT_MS = 10_000;
63	
64	/** Max length for any absolute path we accept from the client. */
65	export const MAX_PATH_LEN = 4096;
66	/** Max length for a single path segment (file/folder name). */
67	export const MAX_NAME_LEN = 255;
68	
69	/**
70	 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
71	 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
72	 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
73	 * "/". Throws on anything suspicious — callers surface the message.
74	 */
75	export function normalizePath(input: string): string {
76	  if (typeof input !== "string") throw new Error("Invalid path.");
77	  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
78	  if (input.includes("\0")) throw new Error("Invalid path.");
79	  if (!input.startsWith("/")) throw new Error("Path must be absolute.");
80	
81	  const out: string[] = [];
82	  for (const part of input.split("/")) {
83	    if (part === "" || part === ".") continue;
84	    if (part === "..") throw new Error("Path traversal is not allowed.");
85	    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
86	    out.push(part);
87	  }
88	  return "/" + out.join("/");
89	}
90	
91	/**
92	 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
93	 * not "." or "..". Returns the name unchanged if valid.
94	 */
95	export function validateName(name: string): string {
96	  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
97	  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
98	  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
99	  if (name === "." || name === "..") throw new Error("That name is not allowed.");
100	  return name;
101	}
102	
103	/** Join a validated absolute dir with a validated name, re-normalizing. */
104	export function joinPath(dir: string, name: string): string {
105	  return normalizePath(`${dir}/${name}`);
106	}
107	
108	/**
109	 * Resolve the {host, port} for a server, mirroring the server detail page:
110	 * dedicated IP -> :22, otherwise PUBLIC_IP:sshPort.
111	 */
112	export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
113	  const dedicated = !!server.dedicatedIp;
114	  const host = dedicated ? server.dedicatedIp!.address : process.env.PUBLIC_IP || "";
115	  const port = dedicated ? 22 : server.sshPort;
116	  if (!host || !port) return null;
117	  return { host, port };
118	}
119	
120	/**
121	 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
122	 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
123	 * the in-memory filesystem before ever reaching here.
124	 */
125	export async function withSftp<T>(
126	  server: SftpServer,
127	  fn: (client: SftpClient) => Promise<T>
128	): Promise<T> {
129	  if (SANDBOX) {
130	    throw new Error("withSftp must not be called in sandbox mode");
131	  }
132	  const target = connectionTarget(server);
133	  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
134	  const password = serverRootPassword(server);
135	  if (!password) throw new Error("Server has no root password set.");
136	
137	  const client = new SftpClient();
138	  try {
139	    await client.connect({
140	      host: target.host,
141	      port: target.port,
142	      username: "root",
143	      password,
144	      readyTimeout: CONNECT_TIMEOUT_MS,
145	    });
146	    return await fn(client);
147	  } finally {
148	    try {
149	      await client.end();
150	    } catch {
151	      /* best-effort close */
152	    }
153	  }
154	}
