156	// ----------------------------------------------------------------------------
157	// Sandbox in-memory filesystem
158	// ----------------------------------------------------------------------------
159	
160	type SimNode =
161	  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
162	  | { type: "file"; mtime: number; mode: number; content: string };
163	type SimDir = Extract<SimNode, { type: "dir" }>;
164	
165	/** One simulated filesystem per server id, lazily seeded. */
166	const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
167	const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
168	globalForSim.__nxeonSftpSim = simStore;
169	
170	function seedSim(): SimNode {
171	  const now = Date.now();
172	  const file = (content: string, mode = 0o644): SimNode => ({
173	    type: "file",
174	    mtime: now,
175	    mode,
176	    content,
177	  });
178	  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
179	    type: "dir",
180	    mtime: now,
181	    mode,
182	    children,
183	  });
184	  return dir({
185	    root: dir({
186	      "readme.txt": file(
187	        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
188	      ),
189	      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
190	      projects: dir({
191	        "app.js": file("console.log('hello from your server');\n"),
192	        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
193	      }),
194	    }),
195	    etc: dir({
196	      "hostname": file("nxeon-vps\n"),
197	      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
198	    }),
199	    var: dir({
200	      log: dir({
201	        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
202	      }),
203	      www: dir({
204	        html: dir({
205	          "index.html": file("<!doctype html><h1>It works</h1>\n"),
206	        }),
207	      }),
208	    }),
209	    tmp: dir({}),
210	  });
211	}
212	
213	function simRoot(serverId: string): SimNode {
214	  let node = simStore.get(serverId);
215	  if (!node) {
216	    node = seedSim();
217	    simStore.set(serverId, node);
218	  }
219	  return node;
220	}
221	
222	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
223	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
224	  if (!rights) return null;
225	  const bits = (s: string): number =>
226	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
227	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
228	}
229	
230	function splitPath(p: string): string[] {
231	  return p.split("/").filter((s) => s.length > 0);
232	}
233	
234	function simResolve(serverId: string, p: string): SimNode | null {
235	  let node = simRoot(serverId);
236	  for (const part of splitPath(p)) {
237	    if (node.type !== "dir") return null;
238	    const next = node.children[part];
239	    if (!next) return null;
240	    node = next;
241	  }
242	  return node;
243	}
244	
245	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
246	  const parts = splitPath(p);
247	  if (parts.length === 0) return null;
248	  const name = parts[parts.length - 1];
249	  const parentPath = "/" + parts.slice(0, -1).join("/");
250	  const parent = simResolve(serverId, parentPath);
251	  if (!parent || parent.type !== "dir") return null;
252	  return { parent, name };
253	}
254	
255	// ----------------------------------------------------------------------------
256	// Typed operations (sandbox-aware)
257	// ----------------------------------------------------------------------------
258	
259	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
260	  if (SANDBOX) {
261	    const node = simResolve(server.id, path);
262	    if (!node) throw new Error("No such directory.");
263	    if (node.type !== "dir") throw new Error("Not a directory.");
264	    return Object.entries(node.children)
265	      .map(([name, child]) => ({
266	        name,
267	        type: child.type === "dir" ? "d" : "-",
268	        isDirectory: child.type === "dir",
269	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
270	        modifiedMs: child.mtime,
271	        mode: child.mode,
272	      }))
273	      .sort((a, b) =>
274	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
275	      );
276	  }
277	
278	  return withSftp(server, async (client) => {
279	    const list = await client.list(path);
280	    return list
281	      .map((e) => ({
282	        name: e.name,
283	        type: e.type,
284	        isDirectory: e.type === "d",
285	        size: e.size,
286	        modifiedMs: e.modifyTime,
287	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
288	        // mode — derive the octal permission bits from them.
289	        mode: rightsToMode(e.rights),
290	      }))
291	      .sort((a, b) =>
292	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
293	      );
294	  });
295	}
296	
297	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
298	  if (SANDBOX) {
299	    const node = simResolve(server.id, path);
300	    if (!node) throw new Error("No such file or directory.");
301	    return {
302	      isDirectory: node.type === "dir",
303	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
304	      modifiedMs: node.mtime,
305	      mode: node.mode,
306	    };
307	  }
308	
309	  return withSftp(server, async (client) => {
310	    const s = await client.stat(path);
311	    return {
312	      isDirectory: s.isDirectory,
313	      size: s.size,
314	      modifiedMs: s.modifyTime,
315	      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
316	    };
317	  });
318	}
319	
320	/**
321	 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
322	 * the cap so we never buffer an unbounded file into memory / the editor.
323	 */
324	export async function readFileText(
325	  server: SftpServer,
326	  path: string,
327	  maxBytes: number
328	): Promise<string> {
329	  if (SANDBOX) {
330	    const node = simResolve(server.id, path);
331	    if (!node) throw new Error("No such file.");
332	    if (node.type !== "file") throw new Error("Not a file.");
333	    if (Buffer.byteLength(node.content) > maxBytes) {
334	      throw new Error("File is too large to edit in the browser.");
335	    }
336	    return node.content;
337	  }
338	
339	  return withSftp(server, async (client) => {
340	    const s = await client.stat(path);
341	    if (s.isDirectory) throw new Error("Not a file.");
342	    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
343	    const buf = (await client.get(path)) as Buffer;
344	    return buf.toString("utf8");
345	  });
346	}
347	
348	export async function writeFileText(
349	  server: SftpServer,
350	  path: string,
351	  content: string
352	): Promise<void> {
353	  if (SANDBOX) {
354	    const loc = simParent(server.id, path);
355	    if (!loc) throw new Error("Invalid path.");
356	    const existing = loc.parent.children[loc.name];
357	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
358	    loc.parent.children[loc.name] = {
359	      type: "file",
360	      mtime: Date.now(),
361	      mode: existing?.type === "file" ? existing.mode : 0o644,
362	      content,
363	    };
364	    return;
365	  }
366	
367	  await withSftp(server, async (client) => {
368	    await client.put(Buffer.from(content, "utf8"), path);
369	  });
370	}
371	
372	export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
373	  if (SANDBOX) {
374	    const loc = simParent(server.id, path);
375	    if (!loc) throw new Error("Invalid path.");
376	    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
377	    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
378	    return;
379	  }
380	
381	  await withSftp(server, async (client) => {
382	    await client.mkdir(path, false);
383	  });
384	}
385	
386	export async function renamePath(
387	  server: SftpServer,
388	  from: string,
389	  to: string
390	): Promise<void> {
391	  if (SANDBOX) {
392	    const src = simResolve(server.id, from);
393	    if (!src) throw new Error("No such file or directory.");
394	    const dst = simParent(server.id, to);
395	    if (!dst) throw new Error("Invalid destination.");
396	    if (dst.parent.children[dst.name]) {
397	      throw new Error("A file or folder with that name already exists.");
398	    }
399	    const srcLoc = simParent(server.id, from);
400	    if (!srcLoc) throw new Error("Cannot rename the root.");
401	    delete srcLoc.parent.children[srcLoc.name];
402	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
403	    return;
404	  }
405	
406	  await withSftp(server, async (client) => {
407	    await client.rename(from, to);
408	  });
409	}
410	
411	/** Remove a file, or recursively remove a directory. */
412	export async function removePath(server: SftpServer, path: string): Promise<void> {
413	  if (SANDBOX) {
414	    const loc = simParent(server.id, path);
415	    if (!loc) throw new Error("Cannot remove the root.");
416	    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
417	    delete loc.parent.children[loc.name];
418	    return;
419	  }
420	
421	  await withSftp(server, async (client) => {
422	    const s = await client.stat(path);
423	    if (s.isDirectory) {
424	      await client.rmdir(path, true); // recursive
425	    } else {
426	      await client.delete(path);
427	    }
428	  });
429	}
430	
431	export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
432	  if (SANDBOX) {
433	    const node = simResolve(server.id, path);
434	    if (!node) throw new Error("No such file or directory.");
435	    node.mode = mode & 0o777;
436	    return;
437	  }
438	
439	  await withSftp(server, async (client) => {
440	    await client.chmod(path, mode & 0o777);
441	  });
442	}
