444	// ----------------------------------------------------------------------------
445	// Streaming helpers for the upload/download route
446	// ----------------------------------------------------------------------------
447	
448	/** Read an entire file into a Buffer (used by the download endpoint). */
449	export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
450	  if (SANDBOX) {
451	    const node = simResolve(server.id, path);
452	    if (!node) throw new Error("No such file.");
453	    if (node.type !== "file") throw new Error("Not a file.");
454	    return Buffer.from(node.content, "utf8");
455	  }
456	
457	  return withSftp(server, async (client) => {
458	    const s = await client.stat(path);
459	    if (s.isDirectory) throw new Error("Not a file.");
460	    return (await client.get(path)) as Buffer;
461	  });
462	}
463	
464	/** Write a Buffer to a path (used by the upload endpoint). */
465	export async function writeFileBuffer(
466	  server: SftpServer,
467	  path: string,
468	  data: Buffer
469	): Promise<void> {
470	  if (SANDBOX) {
471	    const loc = simParent(server.id, path);
472	    if (!loc) throw new Error("Invalid path.");
473	    const existing = loc.parent.children[loc.name];
474	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
475	    loc.parent.children[loc.name] = {
476	      type: "file",
477	      mtime: Date.now(),
478	      mode: existing?.type === "file" ? existing.mode : 0o644,
479	      content: data.toString("utf8"),
480	    };
481	    return;
482	  }
483	
484	  await withSftp(server, async (client) => {
485	    await client.put(data, path);
486	  });
487	}
