import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
import {
  consolePhase,
  isBuildActive,
  mirrorFanout,
  parseImageDataUrl,
  validateImages,
  buildUserContent,
  parsePlanReply,
  MAX_IMAGES_PER_PROMPT,
  MAX_IMAGE_BASE64_CHARS,
  MIRROR_MIN,
  MIRROR_MAX,
  type ConsoleImage,
} from "../lib/claude-console-core.ts";

/* ------------------------------------------------------------------ *
 * 1. Console state machine — phase is derived only from real status
 * ------------------------------------------------------------------ */

test("consolePhase maps every build status to a coarse UI phase", () => {
  assert.equal(consolePhase(null), "idle");
  assert.equal(consolePhase(undefined), "idle");
  assert.equal(consolePhase("QUEUED"), "planning");
  assert.equal(consolePhase("PLANNING"), "planning");
  assert.equal(consolePhase("AWAITING_APPROVAL"), "awaiting");
  assert.equal(consolePhase("RUNNING"), "running");
  assert.equal(consolePhase("DONE"), "done");
  assert.equal(consolePhase("FAILED"), "failed");
  // An unknown status is idle, never a fabricated "running"/"done".
  assert.equal(consolePhase("WAT"), "idle");
});

test("isBuildActive is true only for in-flight statuses", () => {
  for (const s of ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"]) {
    assert.equal(isBuildActive(s), true, `${s} should be active`);
  }
  for (const s of ["DONE", "FAILED", null, undefined, "NOPE"]) {
    assert.equal(isBuildActive(s as string), false, `${String(s)} should not be active`);
  }
});

/* ------------------------------------------------------------------ *
 * 2. Mirror-mode fan-out
 * ------------------------------------------------------------------ */

test("mirrorFanout expands one prompt into N independent requests sharing a group", () => {
  const reqs = mirrorFanout("build a landing page", ["s1", "s2", "s3"], "grp1");
  assert.equal(reqs.length, 3);
  assert.deepEqual(reqs.map((r) => r.serverId), ["s1", "s2", "s3"]);
  // All share the initial prompt and the mirror group.
  assert.ok(reqs.every((r) => r.prompt === "build a landing page"));
  assert.ok(reqs.every((r) => r.mirrorGroupId === "grp1"));
  // Titles make the relationship legible.
  assert.deepEqual(reqs.map((r) => r.title), ["Variation A", "Variation B", "Variation C"]);
});

test("mirrorFanout allows the SAME server repeated (mirror on one box)", () => {
  const reqs = mirrorFanout("try two variations", ["s1", "s1"], "grp2");
  assert.equal(reqs.length, 2);
  assert.deepEqual(reqs.map((r) => r.serverId), ["s1", "s1"]);
});

test("mirrorFanout trims the shared prompt", () => {
  const reqs = mirrorFanout("   spaced   ", ["a", "b"], "g");
  assert.ok(reqs.every((r) => r.prompt === "spaced"));
});

test("mirrorFanout refuses out-of-range fan-outs rather than launching the wrong count", () => {
  assert.throws(() => mirrorFanout("x", ["only-one"], "g"), /2-6/);
  const seven = Array.from({ length: MIRROR_MAX + 1 }, (_, i) => `s${i}`);
  assert.throws(() => mirrorFanout("x", seven, "g"), /2-6/);
  // Boundaries are allowed.
  assert.equal(mirrorFanout("x", Array(MIRROR_MIN).fill("s"), "g").length, MIRROR_MIN);
  assert.equal(mirrorFanout("x", Array(MIRROR_MAX).fill("s"), "g").length, MIRROR_MAX);
});

