const REPO = join(import.meta.dirname, "..");
const read = (rel: string) => readFileSync(join(REPO, rel), "utf8");

/** Comments stripped, string literals PRESERVED — for copy assertions. */
const withCopy = (rel: string) => stripComments(read(rel));
/** Comments AND string literals blanked — for code-SHAPE assertions. */
const asShape = (rel: string) => stripCommentsAndStrings(read(rel));

const PAGE = "app/dashboard/build/page.tsx";
const STUDIO = "components/customer/claude-code/BuildStudio.tsx";
const CONSOLE = "components/customer/claude-code/BuildConsole.tsx";
const TERMINAL = "components/customer/WebTerminal.tsx";

test("build page no longer hard-blocks the whole page when no key is connected", () => {
  const shape = asShape(PAGE);
  // The old `usable` gate and its early `return` block must be gone entirely.
  assert.ok(!/\busable\b/.test(shape), "the `usable` gate variable must be removed");
  assert.ok(!/if\s*\(\s*!\s*usable\s*\)/.test(shape), "the `if (!usable)` early return must be removed");
  // BuildStudio must render regardless of key state, with keyConnected passed down.
  assert.ok(/return\s*<\s*BuildStudio\b/.test(shape), "the page must render <BuildStudio> as its result");
  assert.ok(/<\s*BuildStudio[\s\S]*keyConnected=/.test(shape), "keyConnected must be passed to BuildStudio");
});

test("build page keeps the 'no running servers' empty state (both modes need one)", () => {
  const shape = asShape(PAGE);
  assert.ok(/servers\.length\s*===\s*0/.test(shape), "the empty state must still gate on zero running servers");
  assert.ok(withCopy(PAGE).includes("No running servers"), "the empty-state copy must remain");
});

test("each console exposes both build modes as a toggle", () => {
  const copy = withCopy(CONSOLE);
  assert.ok(copy.includes("Use my Anthropic key"), "the API-key mode label must exist");
  assert.ok(copy.includes("Use Claude on my server"), "the server-terminal mode label must exist");
  const shape = asShape(CONSOLE);
  // A real toggle: setMode is wired to both modes, and the body branches on mode.
  assert.ok(/setMode\s*\(/.test(shape), "a setMode toggle handler must exist");
  assert.ok(/mode\s*===/.test(shape), "the console body must branch on the selected mode");
});

test("BuildStudio defaults mode from key state and threads keyConnected to consoles", () => {
  const shape = asShape(STUDIO);
  assert.ok(/keyConnected/.test(shape), "BuildStudio must accept and pass keyConnected");
  // Default: key mode when a key exists, server mode otherwise (mirror forces key).
  assert.ok(/initialMode=/.test(shape), "each console must receive an initialMode");
  assert.ok(/keyConnected\s*\?\s*["']?key["']?\s*:\s*["']?server["']?/.test(asShape(STUDIO) + withCopy(STUDIO)) ||
    /keyConnected\s*\?/.test(shape), "initialMode must derive from keyConnected");
});

test("server-terminal mode routes through the REAL WebTerminal + token endpoint, not a fake", () => {
  const shape = asShape(CONSOLE);
  // The console imports and renders the real terminal component.
  assert.ok(
    /import\s*\{[^}]*\bWebTerminal\b[^}]*\}\s*from/.test(shape),
    "BuildConsole must import the real WebTerminal component"
  );
  assert.ok(/<\s*WebTerminal\b/.test(shape), "server-terminal mode must render <WebTerminal>");
  assert.ok(/embedded/.test(shape), "the terminal must be embedded inline in the console pane");

  // And that terminal must genuinely authorize via the ownership-checked token
  // endpoint and connect the PTY websocket — proving it is not a stub.
  const copy = withCopy(TERMINAL);
  assert.ok(copy.includes("/api/terminal/token"), "WebTerminal must mint a token from the ownership-checked endpoint");
  assert.ok(copy.includes("/terminal-ws"), "WebTerminal must connect the real PTY websocket");
  const tShape = asShape(TERMINAL);
  assert.ok(/fetch\s*\(/.test(tShape), "WebTerminal must actually fetch the token (not fabricate one)");
  assert.ok(/new\s+WebSocket\s*\(/.test(tShape), "WebTerminal must open a real WebSocket");
});

test("server-terminal mode copy is honest that it bypasses plan-then-approve", () => {
  const copy = withCopy(CONSOLE);
  // Must say plainly the platform is not reviewing terminal commands.
  assert.ok(
    /does not review them|Nxeon isn't reviewing|not reviewing|straight (on|to) your server/i.test(copy),
    "server-terminal copy must state the platform does not review these commands"
  );
});

