/**
 * Expose programmatic input injection to parents. `sendInput` writes to the
 * PTY using the EXACT same wire frame as an interactive keystroke
 * (`{type:"data",data}`) — the input bar and the keyboard are indistinguishable
 * to the backend. Guarded on an open socket so a message typed before Connect
 * (or after Disconnect) is silently dropped rather than throwing.
 */
useImperativeHandle(
  ref,
  () => ({
    sendInput: (text: string) => {
      const ws = wsRef.current;
      if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify({ type: "data", data: text }));
      }
    },
    isConnected: () => wsRef.current?.readyState === WebSocket.OPEN,
  }),
  []
);

