const termRef = useRef<WebTerminalHandle | null>(null);
const termFileRef = useRef<HTMLInputElement>(null);
const termImageRef = useRef<HTMLInputElement>(null);
// Uploaded attachments referenced in the current terminal prompt (chips).
const [termAttachments, setTermAttachments] = useState<{ name: string; path: string }[]>([]);
const [uploading, setUploading] = useState(false);
const [termNotice, setTermNotice] = useState<string | null>(null);

useEffect(() => () => recognitionRef.current?.stop(), []);

/* -------------------- server-terminal: uploads + send ------------------- */

const MAX_UPLOAD_BYTES = 15 * 1024 * 1024; // mirror the server-side cap

const readAsDataUrl = (file: File): Promise<string> =>
  new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(typeof r.result === "string" ? r.result : "");
    r.onerror = () => reject(new Error("Could not read the file."));
    r.readAsDataURL(file);
  });

// Upload each file to the customer's server over SFTP, then type its remote
// path into the live PTY (so `claude` can read it) and pin a removable chip.
const uploadFilesToServer = useCallback(
  async (files: FileList | File[]) => {
    if (!serverId) return;
    for (const file of Array.from(files)) {
      if (file.size > MAX_UPLOAD_BYTES) {
        setTermNotice(`${file.name} exceeds the 15 MB upload limit.`);
        continue;
      }
      setUploading(true);
      setTermNotice(null);
      try {
        const dataUrl = await readAsDataUrl(file);
        const res = await uploadToServer(serverId, file.name, dataUrl);
        if (res.ok) {
          setTermAttachments((prev) => [...prev, { name: res.name, path: res.path }]);
          // Reference the uploaded path in the terminal exactly as a keystroke.
          termRef.current?.sendInput(res.path + " ");
        } else {
          setTermNotice(res.error);
        }
      } catch (e) {
        setTermNotice(e instanceof Error ? e.message : "Upload failed.");
      } finally {
        setUploading(false);
      }
    }
  },
  [serverId, MAX_UPLOAD_BYTES]
);

// Paste an image straight into the terminal input → upload + reference it.
const onTerminalPaste = useCallback(
  (e: React.ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    const files: File[] = [];
    for (const it of Array.from(items)) {
      if (it.kind === "file") {
        const f = it.getAsFile();
        if (f) files.push(f);
      }
    }
    if (files.length) {
      e.preventDefault();
      void uploadFilesToServer(files);
    }
  },
  [uploadFilesToServer]
);

// Send the composed message into `claude` by typing it + Enter into the PTY.
const sendToTerminal = useCallback(() => {
  const text = input.trim();
  if (!text) return;
  if (!termRef.current?.isConnected()) {
    setTermNotice("Connect the terminal first, then run `claude`.");
    return;
  }
  termRef.current.sendInput(text + "\r");
  setInput("");
  setTermAttachments([]);
  setTermNotice(null);
}, [input]);

/* ------------------------------- render --------------------------------- */

  {server ? (
    <>
      <div className="min-h-0 flex-1 p-2">
        <WebTerminal
          ref={termRef}
          key={server.id}
          servers={[server]}
          embedded
          hint="Press Connect, then run `claude` to start — sign in with your Claude subscription or your own API key."
        />
      </div>

      {/* Rich input bar over the live terminal — Claude-Code-desktop style. */}
      <div className="flex-none border-t border-white/[0.06] bg-white/[0.02] p-2.5">
        {termNotice && (
          <div className="mb-2 rounded-lg border border-amber-500/20 bg-amber-500/10 px-2.5 py-1.5 text-[11px] text-amber-200">
            {termNotice}
          </div>
        )}
        {termAttachments.length > 0 && (
          <div className="mb-2 flex flex-wrap gap-1.5">
            {termAttachments.map((a, i) => (
              <span
                key={`${a.path}-${i}`}
                className="inline-flex items-center gap-1 rounded-lg border border-white/10 bg-white/5 px-2 py-1 text-[11px] text-slate-300"
                title={a.path}
              >
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
                  <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                  <path d="M14 2v6h6" />
                </svg>
                <span className="max-w-[10rem] truncate">{a.name}</span>
                <button
                  type="button"
                  onClick={() => setTermAttachments((prev) => prev.filter((_, j) => j !== i))}
                  className="ml-0.5 text-slate-500 hover:text-white"
                  aria-label={`Remove ${a.name}`}
                >
                  <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
                    <path d="M18 6 6 18M6 6l12 12" />
                  </svg>
                </button>
              </span>
            ))}
          </div>
        )}
        <div className="flex items-end gap-1.5">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onPaste={onTerminalPaste}
            onKeyDown={(e) => {
              if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
