            className="min-h-[42px] flex-1 resize-none rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-[13px] text-white outline-none placeholder:text-slate-600 focus:border-brand-400/60"
          />
          <div className="flex flex-none flex-col gap-1.5">
