                </svg>
              </button>
              {/* Attach image */}
              <input
                ref={termImageRef}
                type="file"
                accept="image/*"
                multiple
                hidden
                onChange={(e) => {
                  if (e.target.files) void uploadFilesToServer(e.target.files);
                  e.target.value = "";
                }}
              />
              <button
                type="button"
                onClick={() => termImageRef.current?.click()}
                disabled={uploading}
                className="rounded-lg border border-white/10 bg-white/5 p-2 text-slate-300 hover:bg-white/10 disabled:opacity-50"
                title="Upload an image to the server"
                aria-label="Upload image"
              >
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <rect x="3" y="3" width="18" height="18" rx="2" />
                  <circle cx="9" cy="9" r="2" />
                  <path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21" />
                </svg>
              </button>
              {speechSupported.current && (
                <button
                  type="button"
                  onClick={toggleVoice}
                  className={`rounded-lg border p-2 ${listening ? "border-red-500/40 bg-red-500/15 text-red-300" : "border-white/10 bg-white/5 text-slate-300 hover:bg-white/10"}`}
                  title={listening ? "Stop dictation" : "Dictate (voice to text)"}
