              {uploading ? "…" : "Send"}
            </button>
          </div>
        </div>
        <p className="mt-1.5 px-0.5 text-[10px] text-slate-500">
          Types straight into the live <code className="rounded bg-white/10 px-1 text-slate-300">claude</code> session over SSH. Uploads land in <code className="rounded bg-white/10 px-1 text-slate-300">~/nxeon-uploads</code>.
        </p>
