import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";
import { sanitizeUploadName, UPLOAD_DIR } from "../lib/actions-files.ts";

/* ------------------------------------------------------------------ *
 * Matrix server-terminal rich input layer.
 *
 * The server-terminal console mode grew a Claude-Code-desktop-style input
 * bar over the live xterm PTY: a send box that types into `claude`, voice
 * dictation, and image/file upload that lands on the customer's server over
 * SFTP. These tripwires assert the wiring is REAL — the send box drives the
 * WebTerminal ref (not planConsoleBuild), the terminal exposes programmatic
 * input through the same WS frame as a keystroke, the idle hint can be
 * dismissed, and the upload action authenticates + ownership-checks + can
 * only ever write a sanitized basename inside one fixed directory.
 * ------------------------------------------------------------------ */

const REPO = join(import.meta.dirname, "..");
const read = (rel: string) => readFileSync(join(REPO, rel), "utf8");
/** Comments stripped, string literals PRESERVED — for copy assertions. */
const withCopy = (rel: string) => stripComments(read(rel));
/** Comments AND string literals blanked — for code-SHAPE assertions. */
const asShape = (rel: string) => stripCommentsAndStrings(read(rel));

const CONSOLE = "components/customer/claude-code/BuildConsole.tsx";
const TERMINAL = "components/customer/WebTerminal.tsx";
const ACTIONS = "lib/actions-files.ts";

/* ------------------------------------------------------------------ *
 * 1. WebTerminal exposes programmatic input through the keystroke frame
 * ------------------------------------------------------------------ */

test("WebTerminal is a forwardRef component exposing an imperative handle", () => {
  const shape = asShape(TERMINAL);
  assert.ok(/forwardRef\s*</.test(shape), "WebTerminal must be a forwardRef component");
  assert.ok(/useImperativeHandle\s*\(/.test(shape), "it must register an imperative handle");
  // The handle surface the parent input bar depends on.
  assert.ok(/sendInput\s*:/.test(shape), "the handle must expose sendInput");
  // A handle type is exported for the parent to type its ref.
  assert.ok(/export\s+type\s+WebTerminalHandle/.test(shape), "WebTerminalHandle type must be exported");
});

test("sendInput routes through the SAME ws {type:'data'} frame as a keystroke, guarded on OPEN", () => {
  const copy = withCopy(TERMINAL);
  const shape = asShape(TERMINAL);
  // The literal frame shape must be present with a "data" type — identical to
  // the term.onData keystroke path, so the PTY can't tell them apart.
  assert.ok(
    /ws\.send\s*\(\s*JSON\.stringify\s*\(\s*\{\s*type\s*:\s*["']data["']/.test(copy),
    "sendInput must send a {type:'data',data} frame over the websocket"
  );
  // It must be guarded on an OPEN socket (never throw when disconnected).
  assert.ok(
    /readyState\s*===\s*WebSocket\.OPEN/.test(shape),
    "sendInput must guard on ws.readyState === WebSocket.OPEN"
  );
  // Exactly the keystroke frame must still exist too (not replaced).
  assert.ok(
    (copy.match(/JSON\.stringify\s*\(\s*\{\s*type\s*:\s*["']data["']/g) ?? []).length >= 2,
    "both the keystroke path and sendInput must emit the data frame"
  );
});

/* ------------------------------------------------------------------ *
 * 2. The idle hint is dismissible
 * ------------------------------------------------------------------ */

test("the terminal idle hint is dismissible via an X + local dismissed state", () => {
  const shape = asShape(TERMINAL);
  // A local dismissed flag gates the hint and is flipped by a button.
  assert.ok(/useState\s*\(\s*false\s*\)/.test(shape), "a boolean dismissed state must exist");
  assert.ok(/hintDismissed/.test(shape), "the hint must be gated on a dismissed flag");
  // The hint only renders while NOT dismissed, and a control sets it true.
  assert.ok(/!\s*hintDismissed/.test(shape), "the hint render must check !hintDismissed");
  assert.ok(/setHintDismissed\s*\(\s*true\s*\)/.test(shape), "an X control must dismiss the hint");
  const copy = withCopy(TERMINAL);
  assert.ok(/Dismiss/i.test(copy), "the dismiss control must be labelled for a11y");
});

test("embedded mode hides WebTerminal's own server dropdown (parent already picks)", () => {
  const shape = asShape(TERMINAL);
  // The <select> of servers must be gated behind !embedded.
  assert.ok(
    /\{\s*!\s*embedded\s*&&[\s\S]*?<\s*select/.test(shape),
    "the in-terminal server <select> must be gated on !embedded"
  );
  // Connect/Disconnect + status remain unconditional (still present).
  const copy = withCopy(TERMINAL);
  assert.ok(copy.includes("Connect") && copy.includes("Disconnect"), "Connect/Disconnect must remain");
});

/* ------------------------------------------------------------------ *
 * 3. Server-mode Send injects into the terminal, NOT the plan pipeline
 * ------------------------------------------------------------------ */

test("server-terminal Send types into the live PTY via the ref, carriage-return submits", () => {
  const shape = asShape(CONSOLE);
  // A dedicated send handler drives the terminal ref, not planConsoleBuild.
  assert.ok(/termRef\s*=\s*useRef/.test(shape), "the console must hold a WebTerminal ref");
  assert.ok(/<\s*WebTerminal[\s\S]*ref\s*=\s*\{\s*termRef\s*\}/.test(shape), "the ref must be attached to <WebTerminal>");
  assert.ok(/termRef\.current[\s\S]*sendInput\s*\(/.test(shape), "Send must call the ref's sendInput");
  // The submit must append a carriage return so `claude` receives the line.
  assert.ok(
    /sendInput\s*\(\s*text\s*\+\s*["']\\r["']\s*\)/.test(withCopy(CONSOLE)),
    "the sent text must be terminated with a carriage return"
  );
});

test("server-mode Send does NOT route through planConsoleBuild (that's key-mode only)", () => {
  const shape = asShape(CONSOLE);
  // The sendToTerminal handler must exist and be wired to the Send button.
  assert.ok(/sendToTerminal\s*=/.test(shape), "a sendToTerminal handler must exist");
  // planConsoleBuild is still used by key-mode's `send`, but the terminal path
  // must not call it: the sendToTerminal body must reference sendInput, not plan.
  const body = shape.slice(shape.indexOf("sendToTerminal"), shape.indexOf("sendToTerminal") + 400);
  assert.ok(/sendInput/.test(body), "sendToTerminal must inject via sendInput");
  assert.ok(!/planConsoleBuild/.test(body), "sendToTerminal must not call planConsoleBuild");
});

/* ------------------------------------------------------------------ *
 * 4. Server-mode input bar: voice + image + file upload controls
 * ------------------------------------------------------------------ */

test("server-mode reuses the graceful voice-to-text control", () => {
  const shape = asShape(CONSOLE);
  // Speech is feature-detected and the mic is only rendered when supported.
  assert.ok(/getSpeechRecognitionCtor\s*\(/.test(shape), "voice must feature-detect the Web Speech API");
  assert.ok(/speechSupported\.current\s*&&/.test(shape), "the mic must be hidden where unsupported");
  assert.ok(/toggleVoice/.test(shape), "the mic must reuse the existing toggleVoice handler");
});

test("server-mode uploads land on the server over SFTP and are referenced in the terminal", () => {
  const shape = asShape(CONSOLE);
  // Uploads go through the ownership-checked server action, not a data URL.
  assert.ok(/uploadToServer\s*\(/.test(shape), "attachments must upload via the uploadToServer action");
  // The returned remote path is typed into the PTY (so `claude` can read it).
  assert.ok(/res\.path/.test(shape), "the remote path must be referenced");
  assert.ok(/sendInput\s*\(\s*res\.path/.test(shape), "the remote path must be injected into the terminal");
  // Both a file control and an image control exist, plus paste-to-upload.
  assert.ok(/type\s*=\s*["']file["']/.test(withCopy(CONSOLE)), "a file input must exist");
  assert.ok(/onTerminalPaste/.test(shape), "pasting an image must upload it");
});

/* ------------------------------------------------------------------ *
 * 5. The upload action: auth + ownership + sanitized, capped, fixed dir
 * ------------------------------------------------------------------ */

test("uploadToServer authenticates and ownership-checks before touching SFTP", () => {
  const shape = asShape(ACTIONS);
  const start = shape.indexOf("export async function uploadToServer");
  assert.ok(start !== -1, "uploadToServer must be exported");
  const end = shape.indexOf("export async function", start + 10);
  const body = shape.slice(start, end === -1 ? undefined : end);
  // Ownership gate: ownedServer wraps requireUser + userId===caller (see below).
  assert.ok(/ownedServer\s*\(/.test(body), "it must resolve the server through the ownership-checked ownedServer");
  // It writes the buffer through the SFTP helper and returns a remote path.
  assert.ok(/writeFileBuffer\s*\(/.test(body), "it must write via writeFileBuffer");
  assert.ok(/sanitizeUploadName\s*\(/.test(body), "the filename must be sanitized");
  assert.ok(/joinPath\s*\(\s*UPLOAD_DIR/.test(body), "the destination must be UPLOAD_DIR + a sanitized name");
});

test("ownedServer enforces requireUser + per-user ownership (userId === caller)", () => {
  const shape = asShape(ACTIONS);
  const start = shape.indexOf("async function ownedServer");
  const body = shape.slice(start, start + 700);
  assert.ok(/requireUser\s*\(/.test(body), "ownedServer must authenticate via requireUser");
  assert.ok(/server\.userId\s*!==\s*user\.id/.test(body), "ownedServer must reject a non-owner (unless admin)");
});

test("uploadToServer caps upload size and never writes outside the fixed uploads dir", () => {
  const shape = asShape(ACTIONS);
  const copy = withCopy(ACTIONS);
  // A concrete byte cap exists and is checked against the decoded buffer.
  assert.ok(/MAX_UPLOAD_BYTES/.test(shape), "a MAX_UPLOAD_BYTES cap must exist");
  assert.ok(/buffer\.length\s*>\s*MAX_UPLOAD_BYTES/.test(shape), "the decoded size must be checked against the cap");
  assert.ok(/15\s*\*\s*1024\s*\*\s*1024/.test(shape), "the cap must be 15 MB");
  // The uploads dir is a fixed absolute path — never a client-chosen path.
  assert.ok(copy.includes("/root/nxeon-uploads"), "uploads must be pinned to /root/nxeon-uploads");
});

/* ------------------------------------------------------------------ *
 * 6. Pure filename sanitizer — the traversal tripwire, unit-tested
 * ------------------------------------------------------------------ */

test("sanitizeUploadName reduces any hostile path to a safe basename", () => {
  // Directory components (POSIX + Windows) are stripped to the final segment.
  assert.equal(sanitizeUploadName("logo.png"), "logo.png");
  assert.equal(sanitizeUploadName("../../etc/passwd"), "passwd");
  assert.equal(sanitizeUploadName("/etc/shadow"), "shadow");
  assert.equal(sanitizeUploadName("C:\\Windows\\evil.exe"), "evil.exe");
  assert.equal(sanitizeUploadName("nested/dir/report.pdf"), "report.pdf");
  assert.equal(sanitizeUploadName("  spaced.txt  "), "spaced.txt");
});

test("sanitizeUploadName rejects names that resolve to traversal or nothing", () => {
  // A name that is only traversal / separators has no safe basename.
  assert.throws(() => sanitizeUploadName(".."), /allowed|name/i);
  assert.throws(() => sanitizeUploadName("../.."), /allowed|name/i);
  assert.throws(() => sanitizeUploadName("/"), /required|name/i);
  assert.throws(() => sanitizeUploadName(""), /required|name/i);
  assert.throws(() => sanitizeUploadName("\0"), /invalid|name/i);
  // The sanitized name never contains a separator or NUL.
  const ok = sanitizeUploadName("a/b/c.txt");
  assert.ok(!ok.includes("/") && !ok.includes("\0"), "result must be a bare basename");
});

test("UPLOAD_DIR is a fixed absolute path under /root", () => {
  assert.equal(UPLOAD_DIR, "/root/nxeon-uploads");
});

