test("the terminal idle hint is dismissible via an X + local dismissed state", () => {
  // NOTE: this hint region contains inline JSX (`<code>…</code>`, `</>`) with a
  // "/" inside a className, which the source-stripping helpers mis-lex — so the
  // structural wiring is asserted against RAW source. `setHintDismissed` /
  // `hintDismissed` can only ever be real code (never string/comment content),
  // so a raw match here is safe.
  const raw = read(TERMINAL);
  // A local dismissed flag with a setter, initialised false.
  assert.ok(/const\s*\[\s*hintDismissed\s*,\s*setHintDismissed\s*\]\s*=\s*useState\s*\(\s*false\s*\)/.test(raw),
    "a boolean hintDismissed state must exist");
  // The hint only renders while NOT dismissed.
  assert.ok(/!\s*hintDismissed/.test(raw), "the hint render must check !hintDismissed");
  // An X control flips it to true.
  assert.ok(/setHintDismissed\s*\(\s*true\s*\)/.test(raw), "an X control must dismiss the hint");
  const copy = withCopy(TERMINAL);
  assert.ok(/Dismiss/i.test(copy), "the dismiss control must be labelled for a11y");
});

